package co.kr.badara.dolswevoice;
import android.app.*;import android.os.*;import android.content.*;import java.util.*;import org.json.*;
/** Emulator instrumentation; isolated preferences, no HA network or device action. */
public final class AndroidLockConfigTests extends Instrumentation {
 int checks;void ok(boolean b){checks++;if(!b)throw new AssertionError("Lock config check "+checks);}interface Task{void run()throws Exception;}void fails(Task t)throws Exception{boolean rejected=false;try{t.run();}catch(Exception e){rejected=true;}ok(rejected);}
 public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle out=new Bundle();Config cfg=null;try{Context scoped=new ContextWrapper(getTargetContext()){public Context getApplicationContext(){return this;}public android.content.SharedPreferences getSharedPreferences(String n,int mode){return super.getSharedPreferences("lock-test-isolated",mode);}};cfg=new Config(scoped);cfg.p.edit().clear().commit();final Config c=cfg;JSONObject alias=new JSONObject().put("lock.front","현관문");Map<String,String> changes=new HashMap<>();changes.put("lock.front","000042");c.saveDeviceSettings(alias,changes,Collections.emptySet());ok(c.hasLockCode("lock.front"));ok(c.lockCode("lock.front").equals("000042"));String encrypted=c.p.getString("lockCodes","");ok(!new JSONObject(encrypted).getString("lock.front").equals("000042"));changes.put("lock.front","");c.saveDeviceSettings(alias,changes,Collections.emptySet());ok(c.lockCode("lock.front").equals("000042"));ok(c.p.getString("lockCodes","").equals(encrypted));changes.put("lock.front","007531");c.saveDeviceSettings(alias,changes,Collections.emptySet());ok(c.lockCode("lock.front").equals("007531"));String before=c.p.getString("lockCodes","");JSONObject duplicate=new JSONObject().put("lock.front","현관문").put("lock.back","현관 문");fails(()->c.saveDeviceSettings(duplicate,changes,Collections.emptySet()));ok(c.p.getString("lockCodes","").equals(before));fails(()->c.saveDeviceSettings(alias,changes,new HashSet<>(Arrays.asList("lock.front"))));ok(c.lockCode("lock.front").equals("007531"));changes.put("lock.front","");c.saveDeviceSettings(alias,changes,new HashSet<>(Arrays.asList("lock.front")));ok(!c.hasLockCode("lock.front")&&c.lockCode("lock.front").isEmpty());ok(c.alias("lock.front").equals("현관문"));out.putString("stream","ANDROID_LOCK_CONFIG_OK "+checks+" checks: Keystore encryption, leading zeros, empty preserves, replacement, deletion, atomic validation");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("stream","ANDROID_LOCK_CONFIG_FAIL "+e);finish(Activity.RESULT_CANCELED,out);}finally{if(cfg!=null)cfg.p.edit().clear().commit();}}
}
